--
-- Name: sync_employee_job_data(); Type: FUNCTION; Schema: public; Owner: kafu_user
--

CREATE FUNCTION public.sync_employee_job_data() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update all employees that have this job_code
    UPDATE employees
    SET 
        job_title = NEW.title,
        division = COALESCE(NEW.division, employees.division),
        unit = COALESCE(NEW.unit, employees.unit),
        department = COALESCE(NEW.department, employees.department),
        section = COALESCE(NEW.section, employees.section),
        location = COALESCE(NEW.location, employees.location),
        updated_at = NOW()
    WHERE job_code = NEW.code
        AND (
            -- Only update if something actually changed
            job_title IS DISTINCT FROM NEW.title OR
            (division IS DISTINCT FROM NEW.division AND NEW.division IS NOT NULL) OR
            (unit IS DISTINCT FROM NEW.unit AND NEW.unit IS NOT NULL) OR
            (department IS DISTINCT FROM NEW.department AND NEW.department IS NOT NULL) OR
            (section IS DISTINCT FROM NEW.section AND NEW.section IS NOT NULL) OR
            (location IS DISTINCT FROM NEW.location AND NEW.location IS NOT NULL)
        );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_employee_job_data() OWNER TO kafu_user;

--
-- Name: FUNCTION sync_employee_job_data(); Type: COMMENT; Schema: public; Owner: kafu_user
--

COMMENT ON FUNCTION public.sync_employee_job_data() IS 'Automatically updates employee job-related fields when a job is updated in the jobs table';


--
-- Name: sync_job_to_employees(); Type: FUNCTION; Schema: public; Owner: kafu_user
--

CREATE FUNCTION public.sync_job_to_employees() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only update employees when job details change
    -- Preserve employee-specific fields like location, grade, etc.
    UPDATE employees 
    SET 
        job_title = NEW.title,
        division = NEW.division,
        department = NEW.department,
        unit = NEW.unit,
        section = NEW.section,
        updated_at = NOW()
    WHERE job_code = NEW.code;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_job_to_employees() OWNER TO kafu_user;

