--
-- Name: performance_reviews; Type: TABLE; Schema: public; Owner: kafu_user
--

CREATE TABLE public.performance_reviews (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    review_request_id text NOT NULL,
    employee_id text NOT NULL,
    competency_id text NOT NULL,
    assessor_id text NOT NULL,
    current_level text,
    manager_selected_level text,
    assessor_assigned_level text,
    assessment_score integer,
    assessment_percentage numeric(5,2),
    last_assessment_date timestamp without time zone,
    assessor_comments text,
    strengths text,
    gaps text,
    recommendations text,
    development_plan text,
    review_date timestamp without time zone DEFAULT now(),
    next_review_date timestamp without time zone,
    is_finalized boolean DEFAULT false,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    CONSTRAINT performance_reviews_assessor_assigned_level_check CHECK ((assessor_assigned_level = ANY (ARRAY['BASIC'::text, 'INTERMEDIATE'::text, 'ADVANCED'::text, 'MASTERY'::text]))),
    CONSTRAINT performance_reviews_current_level_check CHECK ((current_level = ANY (ARRAY['BASIC'::text, 'INTERMEDIATE'::text, 'ADVANCED'::text, 'MASTERY'::text]))),
    CONSTRAINT performance_reviews_manager_selected_level_check CHECK ((manager_selected_level = ANY (ARRAY['BASIC'::text, 'INTERMEDIATE'::text, 'ADVANCED'::text, 'MASTERY'::text])))
);


ALTER TABLE public.performance_reviews OWNER TO kafu_user;

--
-- Name: TABLE performance_reviews; Type: COMMENT; Schema: public; Owner: kafu_user
--

COMMENT ON TABLE public.performance_reviews IS 'Stores completed performance reviews with detailed feedback';


