-- Name: jobs trigger_sync_employee_job_data; Type: TRIGGER; Schema: public; Owner: kafu_user
--

CREATE TRIGGER trigger_sync_employee_job_data AFTER UPDATE ON public.jobs FOR EACH ROW WHEN (((old.title IS DISTINCT FROM new.title) OR (old.division IS DISTINCT FROM new.division) OR (old.unit IS DISTINCT FROM new.unit) OR (old.department IS DISTINCT FROM new.department) OR (old.section IS DISTINCT FROM new.section) OR (old.location IS DISTINCT FROM new.location))) EXECUTE FUNCTION public.sync_employee_job_data();


--
-- Name: TRIGGER trigger_sync_employee_job_data ON jobs; Type: COMMENT; Schema: public; Owner: kafu_user
--

COMMENT ON TRIGGER trigger_sync_employee_job_data ON public.jobs IS 'Triggers employee job data sync when job is updated';


